package vn.edu.fpt.seal.modules.chat.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import vn.edu.fpt.seal.modules.chat.dto.*; import vn.edu.fpt.seal.modules.chat.service.TeamChatService; import vn.edu.fpt.seal.security.CurrentUser; import java.util.*; @RestController @RequestMapping("/team-chat") @RequiredArgsConstructor public class TeamChatController{private final TeamChatService service; @GetMapping @PreAuthorize("isAuthenticated()") public ResponseEntity<List<TeamChatMessageResponse>> list(@RequestParam UUID teamId){return ResponseEntity.ok(service.list(teamId));} @PostMapping @PreAuthorize("isAuthenticated()") public ResponseEntity<TeamChatMessageResponse> create(@AuthenticationPrincipal CurrentUser user,@Valid @RequestBody CreateTeamChatMessageRequest r){return ResponseEntity.ok(service.create(r,user.getId()));}}
